#!/usr/bin/env bash
# EdgeCore runtime launcher - generated by edgecore.package
# Usage: bin/run.sh --mode generate --prompt "..." [runtime args...]
set -euo pipefail
DIR="$(cd "$(dirname "$0")/.." && pwd)"
exec "$DIR/bin/edgecore-runtime" \
  --model "$DIR/model.ecm" \
  --threads 1 \
  --batch 1 \
  --affinity none \
  "$@"
